<div class="section-heading"><div><div class="eyebrow">Agenda 2.0</div><h1>Regras da agenda</h1><p class="text-secondary mb-0">Controle antecedência, intervalo entre atendimentos e autoatendimento do cliente.</p></div><a class="btn btn-light" href="/schedule/blocks">Folgas e bloqueios</a></div><div class="card"><div class="card-body"><form method="post" action="/schedule/settings" class="row g-3"><?=
\App\Core\CSRF::field()?><div class="col-md-4"><label class="form-label">Antecedência mínima</label><div class="input-group"><input class="form-control" type="number" min="0" name="minimum_notice_minutes" value="<?=(int)$settings['minimum_notice_minutes']?>"><span class="input-group-text">min</span></div></div><div class="col-md-4"><label class="form-label">Máximo para agendar</label><div class="input-group"><input class="form-control" type="number" min="1" max="365" name="maximum_days_ahead" value="<?=(int)$settings['maximum_days_ahead']?>"><span class="input-group-text">dias</span></div></div><div class="col-md-4"><label class="form-label">Intervalo da grade</label><div class="input-group"><input class="form-control" type="number" min="5" max="60" name="slot_interval_minutes" value="<?=(int)$settings['slot_interval_minutes']?>"><span class="input-group-text">min</span></div></div><div class="col-md-4"><label class="form-label">Respiro entre clientes</label><div class="input-group"><input class="form-control" type="number" min="0" max="120" name="buffer_minutes" value="<?=(int)$settings['buffer_minutes']?>"><span class="input-group-text">min</span></div></div><div class="col-md-4"><label class="form-label">Prazo mínimo para cancelar</label><div class="input-group"><input class="form-control" type="number" min="0" name="cancel_notice_minutes" value="<?=(int)$settings['cancel_notice_minutes']?>"><span class="input-group-text">min</span></div></div><div class="col-12"><div class="d-flex flex-wrap gap-4"><label class="form-check"><input class="form-check-input" type="checkbox" name="customer_can_cancel" <?=$settings['customer_can_cancel']?'checked':''?>> Cliente pode cancelar pelo link</label><label class="form-check"><input class="form-check-input" type="checkbox" name="customer_can_reschedule" <?=$settings['customer_can_reschedule']?'checked':''?>> Cliente pode remarcar pelo link</label><label class="form-check"><input class="form-check-input" type="checkbox" name="reminder_24h_enabled" <?=$settings['reminder_24h_enabled']?'checked':''?>> Lembrete 24h</label><label class="form-check"><input class="form-check-input" type="checkbox" name="reminder_2h_enabled" <?=$settings['reminder_2h_enabled']?'checked':''?>> Lembrete 2h</label></div></div><div class="col-12"><button class="btn btn-primary">Salvar regras</button></div></form></div></div>
